    "dictate.modelNote": "\u043E\u043A\u043E\u043B\u043E {time} \u043D\u0430 \u0444\u0440\u0430\u0437\u0443 \u043D\u0430 \u044D\u0442\u043E\u043C \u043A\u043E\u043C\u043F\u044C\u044E\u0442\u0435\u0440\u0435",
