    "meet.note": "\u0437\u0430\u043F\u0438\u0441\u0430\u0442\u044C \u0437\u0432\u043E\u043D\u043E\u043A \u0432 Chrome \u0441 \u0440\u0430\u0441\u0448\u0438\u0440\u0435\u043D\u0438\u0435\u043C Krya",
