    "kb.partBadge": "\u0437\u043D\u0430\u0447\u043E\u043A \u0440\u043E\u0437\u043A\u043B\u0430\u0434\u043A\u0438",
    "kb.partKeys": "\u0443\u0441\u0456 \u043A\u043B\u0430\u0432\u0456\u0448\u0456 Krya",
