    "about.online": "\u0432\u0438\u0445\u043E\u0434\u0438\u0442\u044C \u0432 \u0456\u043D\u0442\u0435\u0440\u043D\u0435\u0442 \u043B\u0438\u0448\u0435 \u0434\u043B\u044F",
